import Link from 'next/link'
import { notFound, redirect } from 'next/navigation'
import { createClient, getUserId } from '@/lib/supabase/server'
import { CompetitionView, type Fixture, type LadderRow } from './competition-view'

export default async function CompetitionPage(props: {
  params: Promise<{ competitionId: string }>
  /** `?tab=run|ladder|discipline|referees|clubs|send` opens that tab — what Home links to. */
  searchParams: Promise<{ tab?: string }>
}) {
  const { competitionId } = await props.params
  const { tab: initialTab } = await props.searchParams
  const supabase = await createClient()

  const userId = await getUserId()
  if (!userId) redirect('/signin')

  const { data: comp } = await supabase
    .from('competitions')
    .select('id, name, type, season, organiser, organiser_id, starts_on, status, mode, academies!organiser_id(name)')
    .eq('id', competitionId)
    .maybeSingle()

  if (!comp) notFound()
  const runBy = orgName(comp.academies) ?? comp.organiser

  const [{ data: sheet }, { data: entries }, { data: access }] = await Promise.all([
    supabase.rpc('competition_run_sheet', { p_competition: competitionId }),
    supabase
      .from('competition_entries')
      .select('id, display_name, division, group_label, academy_id')
      .eq('competition_id', competitionId)
      .order('division')
      .order('group_label')
      .order('display_name'),
    // L-13: owner/admin, or a league role scoped to an area.
    supabase.rpc('my_competition_access', { p_competition: competitionId }),
  ])

  const areas = ((access as unknown as { areas?: string[] } | null)?.areas ?? []) as string[]
  const isOrganiser = areas.includes('competition')
  const divisions = [...new Set((entries ?? []).map((e) => e.division))]

  // Asked for separately, and allowed to fail.
  //
  // public_slug and published_at arrive with 0079. Adding them to the select
  // above would make the whole page a PostgREST error on any database that
  // does not have them yet — the publish control is worth having, and not at
  // the cost of the screen it lives on.
  // The cast is because lib/database.types.ts is generated from the DEPLOYED
  // schema, which does not have these columns yet, so the typed client turns
  // the select into a compile error about a column it has never heard of.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const loose = supabase as any
  const { data: publication } = (await loose
    .from('competitions')
    .select('public_slug, published_at, entries_open')
    .eq('id', competitionId)
    .maybeSingle()) as {
    data: { public_slug: string | null; published_at: string | null; entries_open: boolean | null } | null
  }

  // One ladder per division, computed rather than stored.
  const ladders: Record<string, LadderRow[]> = {}
  for (const d of divisions) {
    const { data } = await supabase.rpc('competition_ladder', {
      p_competition: competitionId,
      p_division: d,
    })
    ladders[d] = (data ?? []) as LadderRow[]
  }

  return (
    <main className="mx-auto max-w-md">
      <header className="border-b border-[var(--line)] p-5">
        <Link href="/competitions" className="text-sm text-ink-2">← Competitions</Link>
        <h1 className="mt-2 text-2xl font-semibold" style={{ color: 'var(--brand-text)' }}>{comp.name}</h1>
        <p className="mt-0.5 text-sm capitalize text-ink-2">
          {[comp.type.replace('_', ' '), comp.season].filter(Boolean).join(' · ')}
        </p>
        {/* "Run by <Group>" (0246). The organiser's own row is withheld from
            another club's people by policy; the competition carries the
            group's name for exactly that. */}
        {runBy && <p className="text-sm text-ink-2" data-run-by>Run by {runBy}</p>}
      </header>

      <CompetitionView
        status={comp.status}
        competitionId={comp.id}
        initialTab={initialTab}
        mode={comp.mode}
        isOrganiser={isOrganiser}
        areas={areas}
        entriesOpen={Boolean(publication?.entries_open)}
        name={comp.name}
        publication={
          publication
            ? { slug: publication.public_slug, publishedAt: publication.published_at }
            : null
        }
        divisions={divisions}
        fixtures={(sheet ?? []) as Fixture[]}
        ladders={ladders}
        entries={(entries ?? []).map((e) => ({
          id: e.id,
          name: e.display_name,
          division: e.division,
          group: e.group_label,
          signedUp: e.academy_id !== null,
        }))}
      />
    </main>
  )
}

function orgName(rel: unknown): string | null {
  const one = Array.isArray(rel) ? rel[0] : rel
  return (one as { name?: string } | null)?.name ?? null
}
